from AlgorithmImports import *
from collections import deque
import math


class TwoSlotStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {
            ticker: self.AddEquity(ticker, Resolution.Daily).Symbol
            for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        }

        self.spy_closes = deque(maxlen=101)
        self.aapl_closes = deque(maxlen=3)

        self.rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.spy_previous_sma = None

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.eligible_slot = 1
        self.closed_round_trip_this_bar = False

    def OnData(self, data: Slice):
        self.closed_round_trip_this_bar = False

        bars = {}
        for ticker, symbol in self.symbols.items():
            if not data.Bars.ContainsKey(symbol):
                return
            bars[ticker] = data.Bars[symbol]

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)
        self.rsi.Update(bars["AAPL"].EndTime, aapl_close)

        spy_sma = None
        if len(self.spy_closes) >= 100:
            spy_sma = sum(list(self.spy_closes)[-100:]) / 100.0

        if (
            spy_sma is None
            or self.spy_previous_sma is None
            or not self.rsi.IsReady
            or len(self.aapl_closes) < 3
        ):
            self.spy_previous_sma = spy_sma
            return

        spy_previous_close = list(self.spy_closes)[-2]
        spy_crosses_above = (
            spy_previous_close <= self.spy_previous_sma
            and spy_close > spy_sma
        )
        spy_crosses_below = (
            spy_previous_close >= self.spy_previous_sma
            and spy_close < spy_sma
        )

        aapl_closes_list = list(self.aapl_closes)
        aapl_red_three_days = (
            aapl_closes_list[0] > aapl_closes_list[1]
            and aapl_closes_list[1] > aapl_closes_list[2]
        )
        aapl_rsi_above_60 = self.rsi.Current.Value > 60

        if self.eligible_slot == 1 and self.strategy_a_lot > 0:
            if spy_crosses_below:
                self.MarketOrder(self.symbols["SPY"], -self.strategy_a_lot)
                self.strategy_a_lot = 0
                self.eligible_slot = 2
                self.closed_round_trip_this_bar = True

        elif self.eligible_slot == 2 and self.strategy_b_lot > 0:
            if aapl_rsi_above_60:
                self.MarketOrder(self.symbols["AAPL"], -self.strategy_b_lot)
                self.strategy_b_lot = 0
                self.eligible_slot = 1
                self.closed_round_trip_this_bar = True

        if not self.closed_round_trip_this_bar:
            if self.eligible_slot == 1 and self.strategy_a_lot == 0:
                if spy_crosses_above:
                    target_value = self.Portfolio.TotalPortfolioValue * 0.40
                    quantity = math.floor(target_value / spy_close)

                    if quantity > 0:
                        self.MarketOrder(self.symbols["SPY"], quantity)
                        self.strategy_a_lot = quantity

            elif self.eligible_slot == 2 and self.strategy_b_lot == 0:
                if aapl_red_three_days:
                    if self.Portfolio.Cash >= 20000:
                        quantity = math.floor(20000 / aapl_close)

                        if quantity > 0:
                            self.MarketOrder(self.symbols["AAPL"], quantity)
                            self.strategy_b_lot = quantity

        self.spy_previous_sma = spy_sma
